div.script:

function switchHosoMainTab(tabContentId, btnEl) {
    document.getElementById('content_tab1').style.display = 'none';
    document.getElementById('content_tab2').style.display = 'none';

    document.getElementById('btn_main_tab1').classList.remove('active');
    document.getElementById('btn_main_tab2').classList.remove('active');

    document.getElementById(tabContentId).style.display = 'block';
    btnEl.classList.add('active');

    const currentUrl = new URL(window.location.href);
    currentUrl.searchParams.set('active_tab', tabContentId === 'content_tab2' ? 'tab2' : 'tab1');
    window.history.replaceState({}, '', currentUrl.toString());
}

function onChangeKyBaoCao(selectEl) {
    const kehoachId = selectEl.value;
    if (!kehoachId) return;

    const url = new URL(window.location.href);
    url.searchParams.set('kehoach_id', kehoachId);
    url.searchParams.set('active_tab', 'tab1');
    window.location.href = url.toString();
}

function onChangeKyThangToi(selectEl) {
    const thangToiId = selectEl.value;
    if (!thangToiId) return;

    const url = new URL(window.location.href);
    url.searchParams.set('thangtoi_id', thangToiId);
    url.searchParams.set('active_tab', 'tab2');
    window.location.href = url.toString();
}

function copyShareUrl(btnEl) {
    const url = btnEl.getAttribute('data-url');
    if (!url) {
        alert("Chưa có liên kết chia sẻ!");
        return;
    }

    if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(url).then(onSuccess).catch(fallbackCopy);
    } else {
        fallbackCopy();
    }

    function fallbackCopy() {
        const tempInput = document.createElement("input");
        tempInput.value = url;
        document.body.appendChild(tempInput);
        tempInput.select();
        document.execCommand("copy");
        document.body.removeChild(tempInput);
        onSuccess();
    }

    function onSuccess() {
        const textSpan = btnEl.querySelector('.copy-btn-text');
        const iconEl = btnEl.querySelector('i');
        const originalText = textSpan.innerText;

        textSpan.innerText = "Đã chép!";
        iconEl.className = "fa fa-check text-success";
        btnEl.style.borderColor = "#86EFAC";
        btnEl.style.backgroundColor = "#F0FDF4";

        setTimeout(function() {
            textSpan.innerText = originalText;
            iconEl.className = "fa fa-link text-primary";
            btnEl.style.borderColor = "#CBD5E1";
            btnEl.style.backgroundColor = "#F8FAFC";
        }, 2000);
    }
}
